select
ub.*,
c.name as categoryName
from user_bill ub
left join category c on ub.category_id = c.id
where ub.ledger_id = #{ledgerId}

    and year(ub.create_time) = #{queryDTO.year}


    and month(ub.create_time) = #{queryDTO.month}


    and day(ub.create_time) = #{queryDTO.day}

order by ub.create_time desc

select
sum(case when type = 1 then amount else 0 end) as income,
sum(case when type = 2 then amount else 0 end) as expense,
sum(case when type = 3 then amount else 0 end) as transfer
from user_bill b
where user_id = #{userId}
and ledger_id = #{ledgerId}

    AND type = #{type}




            AND DATE_FORMAT(b.create_time, '%Y') = #{timeValue}


            AND DATE_FORMAT(b.create_time, '%Y-%m') = #{timeValue}


            AND DATE_FORMAT(b.create_time, '%Y-%m-%d') = #{timeValue}

SELECT c.name AS name, SUM(b.amount) AS value, COUNT(*) AS bill_count FROM user_bill b LEFT JOIN category c ON b.category_id = c.id
b.user_id = #{id} and b.ledger_id = #{ledgerId}
AND b.type = #{type}
AND DATE_FORMAT(b.create_time, '%Y') = #{timeValue}
AND DATE_FORMAT(b.create_time, '%Y-%m') = #{timeValue}
AND DATE_FORMAT(b.create_time, '%Y-%m-%d') = #{timeValue}
GROUP BY c.id, c.name ORDER BY value DESC

