SELECT
DATE_FORMAT(b.create_time, '%Y-%m') DATE_FORMAT(b.create_time, '%Y-%m-%d') DATE_FORMAT(b.create_time, '%Y-%m-%d') DATE_FORMAT(b.create_time, '%Y-%m')
AS timeValue, SUM(CASE WHEN b.type = '1' THEN b.amount ELSE 0 END) - SUM(CASE WHEN b.type = '2' THEN b.amount ELSE 0 END) AS total FROM user_bill b WHERE b.user_id = #{userId} and b.ledger_id = #{ledgerId}
AND b.type = #{type}
AND DATE_FORMAT(b.create_time, '%Y') = #{timeValue}
AND DATE_FORMAT(b.create_time, '%Y-%m') = #{timeValue}
AND DATE_FORMAT(b.create_time, '%Y-%m-%d') = #{timeValue}
GROUP BY timeValue ORDER BY timeValue ASC

